//! The About page of the Settings window (the tray's "About EasyVox" opens it): a header with the
//! app icon, the name, the version and the license; Updates, where Check for Updates shows its
//! answer; then the credits the model licenses require (each offered model's credit and license,
//! original model card, note of changes and the disclaimer) and the third-party notices for the
//! code built into the app.
//!
//! The notices file is generated by `scripts/notices.sh` (cargo-about) into
//! `packaging/THIRD_PARTY_NOTICES.html`, and `scripts/bundle.sh` copies it, with `LICENSE`, into
//! `EasyVox.app/Contents/Resources`.

use crate::brand::{self, Colors};
use crate::controller;
use crate::model_row::{credit_with_link, linked_text, modification_with_link};
use crate::state::{AppStatus, UpdateStatus};
use easyvox_core::models::{self, DISCLAIMER};
use gpui_kit::component::{Disableable as _, h_flex, v_flex};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;
use std::path::PathBuf;

/// The third-party notices, in the bundle's Resources folder.
pub const NOTICES: Resource =
    Resource { bundled: "THIRD_PARTY_NOTICES.html", in_repo: "packaging/THIRD_PARTY_NOTICES.html" };
/// EasyVox's own license.
pub const LICENSE: Resource = Resource { bundled: "LICENSE.txt", in_repo: "LICENSE" };

/// A file `scripts/bundle.sh` copies into `EasyVox.app/Contents/Resources`.
#[derive(Clone, Copy)]
pub struct Resource {
    /// Its name in the bundle.
    bundled: &'static str,
    /// Where it is in the repository.
    #[cfg_attr(not(any(debug_assertions, feature = "self-test")), allow(dead_code))]
    in_repo: &'static str,
}

impl Resource {
    /// The file in the running app's bundle. Outside a bundle (`cargo run`), debug and
    /// self-test builds fall back to the repository's copy.
    pub fn path(self) -> Option<PathBuf> {
        let exe = std::env::current_exe().ok()?;
        let bundled = exe.parent()?.parent()?.join("Resources").join(self.bundled);
        if bundled.is_file() {
            return Some(bundled);
        }
        #[cfg(any(debug_assertions, feature = "self-test"))]
        {
            let repo = PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../..")).join(self.in_repo);
            if repo.is_file() {
                return Some(repo);
            }
        }
        None
    }
}

/// Opens a bundled file in its usual app (the browser for HTML). False if the build has none.
fn open(resource: Resource, cx: &mut App) -> bool {
    match resource.path() {
        Some(path) => {
            cx.open_with_system(&path);
            true
        }
        None => {
            log::warn!("{} isn't in this build (scripts/bundle.sh copies it into the app)", resource.bundled);
            false
        }
    }
}

/// How many model credits the About page drew: the self-test checks that it really draws them.
#[cfg(feature = "self-test")]
pub static DRAWN: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// How many times the Updates row was drawn, for the self-test's check of each state.
#[cfg(feature = "self-test")]
pub static UPDATES_DRAWN: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

const VERSION: &str = env!("CARGO_PKG_VERSION");

const MODELS_INTRO: &str = "EasyVox downloads these models from Hugging Face when you choose them. They aren't part of \
                            EasyVox and keep their own licenses. Each one is saved with a LICENSE.txt that says the same.";

/// The page, drawn from scratch at each render of the Settings window.
pub fn page(c: &'static Colors, cx: &App) -> Div {
    let secondary = rgb(c.ink2);
    let header = v_flex()
        .items_center()
        .pt(px(8.))
        .child(img(brand::ICON_256).size(px(96.)))
        .child(
            div()
                .mt(px(6.))
                .text_size(brand::TEXT_HERO)
                .line_height(px(28.))
                .font_weight(FontWeight::SEMIBOLD)
                .child("EasyVox"),
        )
        .child(div().mt(px(2.)).text_color(secondary).child(format!("Version {VERSION}")))
        .child(div().text_color(secondary).child("Free and open source (MIT) · Made by Brandon Bews"))
        .child(h_flex().mt(px(14.)).gap_2().child(brand::button("about-license", "License").on_click(|_, _, cx| {
            open(LICENSE, cx);
        })))
        .child(
            div().mt(px(14.)).text_size(brand::TEXT_SMALL).text_color(secondary).child("Simple, local speech-to-text."),
        );

    let offered = models::offered();
    let creators = {
        let mut creators: Vec<&str> = offered.iter().map(|m| m.creator).collect();
        creators.dedup();
        creators.join(" or ")
    };
    let credits = offered.into_iter().map(|m| {
        #[cfg(feature = "self-test")]
        DRAWN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let id = m.id;
        let space = px(3.);
        v_flex()
            .py(px(10.))
            .gap(px(2.))
            .child(div().font_weight(FontWeight::MEDIUM).child(m.short_name()))
            .child(
                v_flex()
                    .text_size(brand::TEXT_SMALL)
                    .line_height(px(15.))
                    .text_color(secondary)
                    .child(linked_text(format!("about-{id}-credit"), &format!("{}.", credit_with_link(m)), space))
                    .child(linked_text(
                        format!("about-{id}-card"),
                        &format!("Original model: [{}]({})", without_scheme(m.card_url), m.card_url),
                        space,
                    ))
                    .child(linked_text(
                        format!("about-{id}-changes"),
                        &format!("{}.", modification_with_link(m)),
                        space,
                    ))
                    .child(DISCLAIMER),
            )
            .into_any_element()
    });

    let found = NOTICES.path().is_some();
    let notices = brand::row(
        "Open-source software",
        Some(brand::line(
            c,
            "EasyVox is built on GPUI (Zed Industries), GPUI Kit (Longbridge), transcribe.cpp and ggml, SQLite, \
             Lucide icons and about 450 Rust crates. Their licenses and notices are in one file.",
        )),
        Some(
            brand::button("about-notices", "Third-party notices")
                .when(!found, |b| b.tooltip("Not in this build: scripts/bundle.sh copies it into the app."))
                .on_click(|_, _, cx| {
                    open(NOTICES, cx);
                })
                .into_any_element(),
        ),
    );

    v_flex()
        .child(header)
        .child(brand::group(c, [updates(c, cx)]).mt(px(20.)))
        .child(brand::section("Speech models"))
        .child(brand::group(c, credits))
        .child(brand::footnote(c, format!("{MODELS_INTRO} EasyVox isn't affiliated with or endorsed by {creators}.")))
        .child(div().h(px(20.)))
        .child(brand::group(c, [notices.into_any_element()]))
}

/// The Updates row: what the last check found, and what can be done now. A check runs only when
/// asked, from here (Check Now) or the menu (Check for Updates…), and installs nothing: Download
/// opens the release's page.
fn updates(c: &'static Colors, cx: &App) -> AnyElement {
    #[cfg(feature = "self-test")]
    UPDATES_DRAWN.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let check_now = |enabled: bool| {
        brand::button("update-check", "Check Now")
            .disabled(!enabled)
            .on_click(|_, _, cx| {
                controller::with(cx, |c, cx| c.check_for_updates(cx));
            })
            .into_any_element()
    };
    let (line, control) = match &cx.global::<AppStatus>().update {
        UpdateStatus::Idle => (brand::line(c, "EasyVox checks easyvox.dev only when you ask."), check_now(true)),
        UpdateStatus::Checking => (brand::line(c, "Checking…"), check_now(false)),
        UpdateStatus::Done(Ok(None)) => (brand::line(c, up_to_date(VERSION)), check_now(true)),
        UpdateStatus::Done(Ok(Some(release))) => {
            let url = release.url.clone();
            let later = brand::button("update-later", "Later").on_click(|_, _, cx| {
                controller::with(cx, |c, cx| c.dismiss_update(cx));
            });
            let download = brand::primary("update-download", "Download").on_click(move |_, _, cx| cx.open_url(&url));
            let buttons = h_flex().gap_2().child(later).child(download).into_any_element();
            (brand::line(c, available(&release.version)), buttons)
        }
        UpdateStatus::Done(Err(e)) => {
            (brand::problem(c, e.to_string(), brand::TEXT_SMALL).into_any_element(), check_now(true))
        }
    };
    brand::row("Updates", Some(line), Some(control)).into_any_element()
}

fn up_to_date(version: &str) -> String {
    format!("You're up to date ({version}).")
}

fn available(version: &str) -> String {
    format!("EasyVox {version} is available.")
}

/// "huggingface.co/nvidia/parakeet-tdt-0.6b-v2" for a link's text.
fn without_scheme(url: &str) -> &str {
    url.strip_prefix("https://").unwrap_or(url)
}

#[cfg(test)]
mod tests {
    // Not `super::*`: that brings in GPUI's own `test` macro, which shadows `#[test]`.
    use super::{available, up_to_date};

    #[test]
    fn updates_say_where_you_stand() {
        assert_eq!(up_to_date("0.1.0"), "You're up to date (0.1.0).");
        assert_eq!(available("0.1.1"), "EasyVox 0.1.1 is available.");
    }
}
